 <div class="modal" id="questModal"><div class="modal-box"><div class="modal-head"><h2>Fieldwork & stories</h2><button class="close">×</button></div><div class="modal-body"><p class="notice">The islands are fraying at their edges. Complete these small acts of care to restore their song.</p><ul class="quest-list" id="questList"></ul></div></div></div>
 <div class="modal" id="menuModal"><div class="modal-box"><div class="modal-head"><h2>Journey pause</h2><button class="close">×</button></div><div class="modal-body"><p class="notice">Your adventure is saved automatically on this device.</p><div class="side-actions"><button class="action-btn" data-modal="mapModal">🧭&nbsp; View atlas<span>Explore the islands</span></button><button class="action-btn" data-modal="questModal">✧&nbsp; Fieldwork<span>Story & goals</span></button><button class="action-btn" data-modal="fusionModal">⟲&nbsp; Open the Loom<span>Make a fusion</span></button><button class="action-btn" id="healBtn">♡&nbsp; Rest at camp<span>Restore your team</span></button></div><p class="notice" style="margin-top:15px">Movement: WASD / arrow keys · interact: Space / Enter · pause: Escape</p></div></div></div>
 <div class="modal" id="dialogModal"><div class="modal-box" style="max-width:480px"><div class="modal-body" id="dialogBody"></div></div></div>
 <script>
+const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
+const species=[
+{id:'spriggle',name:'Spriggle',emoji:'🌱',type:'Bloom',color:'#9cdb9e',hp:24,atk:7,move:'Leaf Flick',zone:0},
+{id:'cinderkit',name:'Cinderkit',emoji:'🦊',type:'Ember',color:'#ffad78',hp:21,atk:9,move:'Kindle Pounce',zone:0},
+{id:'tidefin',name:'Tidefin',emoji:'🐟',type:'Tide',color:'#8bcff0',hp:27,atk:6,move:'Ripple Rush',zone:0},
+{id:'mosskip',name:'Mosskip',emoji:'🐸',type:'Bloom',color:'#a6d687',hp:22,atk:7,move:'Bog Bounce',zone:0},
+{id:'pebblit',name:'Pebblit',emoji:'🪨',type:'Stone',color:'#c6b7a0',hp:30,atk:8,move:'Pebble Toss',zone:0},
+{id:'glimmeray',name:'Glimmeray',emoji:'🦋',type:'Gleam',color:'#e4a8f4',hp:20,atk:9,move:'Prism Dust',zone:1},
+{id:'voltkit',name:'Voltkit',emoji:'🐈',type:'Spark',color:'#ffe17d',hp:22,atk:10,move:'Zip Zap',zone:1},
+{id:'frosthorn',name:'Frosthorn',emoji:'🦌',type:'Frost',color:'#a9d8ea',hp:29,atk:7,move:'Snowdrift',zone:1},
+{id:'cloudlet',name:'Cloudlet',emoji:'☁️',type:'Gale',color:'#c5d8ed',hp:25,atk:8,move:'Puff Gust',zone:1},
+{id:'noctowl',name:'Noctowl',emoji:'🦉',type:'Shade',color:'#aa9bcb',hp:27,atk:10,move:'Dusk Dive',zone:2},
+{id:'bloomare',name:'Bloomare',emoji:'🦄',type:'Bloom',color:'#f7a8c9',hp:31,atk:9,move:'Petal Waltz',zone:2},
+{id:'starwhale',name:'Starwhale',emoji:'🐋',type:'Cosmic',color:'#98acff',hp:38,atk:12,move:'Nova Song',zone:2}
+];
+const zones=[{name:'Luma Village',emoji:'🏡',desc:'A quiet home among old roots',weather:'ISLE 01 · MORNING MIST',color:'#72bd8b'},{name:'Prismwild Coast',emoji:'🌊',desc:'Tidal pools & glassy cliffs',weather:'ISLE 02 · SALT & SUN',color:'#72bdc0'},{name:'Starfall Canopy',emoji:'🌌',desc:'An ancient forest in the sky',weather:'ISLE 03 · DUSK EVERMORE',color:'#847cba'}];
+const starters=['spriggle','cinderkit','tidefin'];
+let game={started:false,zone:0,x:5,y:9,dir:'down',party:[],box:[],seen:[],shards:[false,false,false],fusions:[],pods:5,coins:20,steps:0,captures:0,defeats:0,healed:0,quests:{elder:false,capture:false,weave:false,shards:false},flags:{},battle:null,selectedStarter:null};
+let tile=32,ctx,canvas,moveLock=0,toastTimer,dialogState=null;
+function save(){try{localStorage.setItem('mythweave-save',JSON.stringify(game));$('#saveStatus').textContent='● SAVED JUST NOW'}catch(e){}}
+function load(){try{const d=JSON.parse(localStorage.getItem('mythweave-save'));if(d&&d.party){game={...game,...d};game.battle=null;game.started=true;$('#startCover').style.display='none';renderAll();log('Your trail picks up where you left it.')}}catch(e){}}
+function log(text){const el=$('#log');el.innerHTML=`<p>· ${text}</p>`+el.innerHTML;while(el.children.length>5)el.lastChild.remove()}
+function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
+function getSpecies(id){return species.find(s=>s.id===id)||species[0]}
+function makeCreature(id,level=3){const s=getSpecies(id);return {id,name:s.name,emoji:s.emoji,type:s.type,color:s.color,level,max:s.hp+level*2,hp:s.hp+level*2,atk:s.atk+Math.floor(level/2),xp:0,move:s.move, fused:false}}
+function getZoneSpecies(z){return species.filter(s=>s.zone===z)}
+function setupCanvas(){canvas=$('#world');ctx=canvas.getContext('2d');resizeCanvas();window.addEventListener('resize',resizeCanvas);drawWorld()}
+function resizeCanvas(){if(!canvas)return;const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0);drawWorld()}
+function hash(x,y){let n=(x*374761393+y*668265263+game.zone*982451653)|0;n=(n^(n>>13))*1274126177;return ((n^(n>>16))>>>0)/4294967295}
+function terrain(x,y){if(x<0||y<0||x>=24||y>=16)return 'water';if(x===0||x===23||y===0||y===15)return 'water';if((x===5&&y>=8&&y<=11)||(x>=5&&x<=10&&y===10)||(x>=9&&x<=16&&y===7)||(x===15&&y>=4&&y<=7))return 'path';if(x===10&&y===6)return 'plaza';if(x===15&&y===4)return 'shrine';if((hash(x,y)>.80&&!(x<7&&y>8))||((x===3||x===20)&&y>3&&y<13))return 'tree';if(hash(x+40,y+21)>.90)return 'flower';return 'grass'}
+function drawWorld(){if(!ctx||!canvas)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;tile=Math.min(w/24,h/16);const ox=(w-24*tile)/2,oy=(h-16*tile)/2;ctx.clearRect(0,0,w,h);const z=game.zone;
+for(let y=0;y<16;y++)for(let x=0;x<24;x++){let t=terrain(x,y),px=ox+x*tile,py=oy+y*tile;const grass=['#468b71','#4b9277','#43866f'][z],path=['#cbb98e','#c3ad7d','#b3a78a'][z],water=['#397f93','#4f9fa9','#586d9b'][z];ctx.fillStyle=t==='water'?water:t==='path'||t==='plaza'||t==='shrine'?path:grass;ctx.fillRect(px,py,tile+1,tile+1);
+if(t==='water'){ctx.fillStyle='#ffffff20';ctx.fillRect(px+tile*.18,py+tile*.27,tile*.4,2);ctx.fillRect(px+tile*.53,py+tile*.7,tile*.27,1)}else if(t==='grass'||t==='flower'){ctx.fillStyle='#d5f09c44';ctx.fillRect(px+tile*.18,py+tile*.65,2,3);ctx.fillRect(px+tile*.78,py+tile*.24,1,3);if(t==='flower'){ctx.fillStyle=['#ffd67d','#f2a9e3','#e5e9ff'][Math.floor(hash(x+1,y)*3)];ctx.beginPath();ctx.arc(px+tile*.5,py+tile*.48,tile*.08,0,7);ctx.fill()}}else if(t==='path'){ctx.fillStyle='#6b60452a';ctx.fillRect(px+tile*.2,py+tile*.25,3,2);}}
+// landmarks
+const drawEmoji=(x,y,e,size=tile*.72)=>{ctx.font=`${size}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(e,ox+(x+.5)*tile,oy+(y+.51)*tile)};
+for(let y=0;y<16;y++)for(let x=0;x<24;x++)if(terrain(x,y)==='tree'){ctx.font=`${tile*.9}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(z===2?'🌲':'🌳',ox+(x+.5)*tile,oy+(y+.46)*tile)}
+if(z===0){drawEmoji(10,6,'🏡',tile*.85);drawEmoji(16,7,'🌀');drawEmoji(7,8,'🪧',tile*.6);drawEmoji(10,9,'🧑‍🌾',tile*.72)}else if(z===1){drawEmoji(16,7,'🌀');drawEmoji(10,6,'🧙',tile*.75);drawEmoji(8,10,'🪨');drawEmoji(14,9,'🐚')}else{drawEmoji(16,7,'🌀');drawEmoji(10,6,'🦉',tile*.75);drawEmoji(8,8,'✨');drawEmoji(12,10,'🌙')}
+// trainer
+ctx.fillStyle='#10192244';ctx.beginPath();ctx.ellipse(ox+(game.x+.5)*tile,oy+(game.y+.74)*tile,tile*.3,tile*.12,0,0,7);ctx.fill();ctx.font=`${tile*.8}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('🧢',ox+(game.x+.5)*tile,oy+(game.y+.5)*tile);
+}
+function renderAll(){if(!game.started)return;$('#placeName').textContent=zones[game.zone].name;$('#weather').textContent=zones[game.zone].weather;drawWorld();renderParty();renderStats();renderObjective()}
+function renderParty(){const p=$('#partyList');$('#partyCount').textContent=`${game.party.length} / 6${game.box.length?` + ${game.box.length} reserve`:''}`;if(!game.party.length){p.innerHTML='<div class="empty-party">Your weave is quiet. Meet Elder Rowan at the village arch.</div>';return}p.innerHTML=game.party.map((c,i)=>`<div class="party-row"><div class="creature-icon" style="background:${c.color}33">${c.emoji}</div><div class="creature-info"><div class="creature-name">${c.name}${c.fused?' ✧':''}</div><div class="creature-meta">${c.type} · HP ${c.hp}/${c.max}</div><div class="hp-track"><div class="hp-fill ${c.hp/c.max<.25?'low':c.hp/c.max<.55?'mid':''}" style="width:${100*c.hp/c.max}%"></div></div></div><div class="level">Lv.${c.level}</div></div>`).join('')}
+function renderStats(){$('#seenCount').textContent=game.seen.length;$('#fusionCount').textContent=game.fusions.length;$('#shards').innerHTML=game.shards.map(s=>`<i class="shard ${s?'got':''}"></i>`).join('');}
+function renderObjective(){let o=game.party.length===0?'Meet Elder Rowan at the village arch.':game.shards.filter(Boolean).length<3?`Find the ${['Luma','Prismwild','Starfall'][game.shards.findIndex(x=>!x)]} shard at its island shrine.`:'Return to Luma Village and speak with Rowan.';if(game.shards.every(Boolean)&&game.flags.champion)o='The isles are singing again. Make your own path!';$('#objective').textContent=o}
+function startJourney(){game.started=true;$('#startCover').style.display='none';$('#introModal').classList.add('open');buildStarter();renderAll()}
+function buildStarter(){const opts=[{id:'spriggle',tag:'GROVE HEART',copy:'Patient, bright-eyed, and always growing toward the light.'},{id:'cinderkit',tag:'HEARTH HEART',copy:'A little spark with a big brave streak. Warmth follows close.'},{id:'tidefin',tag:'TIDE HEART',copy:'Curious as the current, carrying calm wherever it goes.'}];$('#starterChoices').innerHTML=opts.map(o=>{const s=getSpecies(o.id);return `<button class="starter-card" data-starter="${o.id}"><span class="starter-emoji">${s.emoji}</span><h3>${s.name}</h3><p>${o.copy}</p><span class="type-chip">${o.tag}</span></button>`}).join('');$$('[data-starter]').forEach(b=>b.onclick=()=>{$$('.starter-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');game.selectedStarter=b.dataset.starter;$('#chooseStarter').disabled=false})}
+$('#newGameBtn').onclick=()=>{if(localStorage.getItem('mythweave-save')){game={...game,started:false};}startJourney()};$('#chooseStarter').onclick=()=>{if(!game.selectedStarter)return;game.party=[makeCreature(game.selectedStarter,4)];game.seen=[game.selectedStarter];game.flags.met=true;game.quests.elder=true;$('#introModal').classList.remove('open');toast(`${getSpecies(game.selectedStarter).name} joined your weave!`);log(`You and ${getSpecies(game.selectedStarter).name} set out together.`);save();renderAll()};

