$('#chooseStarter').onclick=()=>{if(!game.selectedStarter)return;game.party=[makeCreature(game.selectedStarter,4)];game.seen=[game.selectedStarter];game.flags.met=true;game.quests.elder=true;$('#introModal').classList.remove('open');toast(`${getSpecies(game.selectedStarter).name} joined your weave!`);log(`You and ${getSpecies(game.selectedStarter).name} set out together.`);save();renderAll()};
const near=(x,y)=>Math.abs(game.x-x)+Math.abs(game.y-y)<=1;
function promptCheck(){let text='';if(game.zone===0&&near(10,9))text='Speak with Elder Rowan';else if(near(16,7))text=game.shards[game.zone]?'Shrine restored · listen again':'Listen to the island shrine';else if(game.zone===0&&near(7,8))text='Read the trail sign';else if(game.zone>0&&near(10,6))text='A wayfarer waves you over';else text='';$('#prompt').innerHTML=text?`<b>SPACE</b> · ${text}`:'';$('#prompt').classList.toggle('show',!!text)}
function interact(){if($('#introModal').classList.contains('open'))return;if(game.zone===0&&near(10,9)){if(!game.flags.rowanTalk){game.flags.rowanTalk=true;dialog('Elder Rowan','“There you are, little weaver. The islands are losing their song. Visit each shrine and bring back its shard. Your companion can help you hear what the stones remember.”','🧙',()=>{log('Rowan asked you to restore the three island shrines.');renderAll();save()})}else dialog('Elder Rowan','“The old loom is yours to use. Two companions, one shared story. Bring your friends together whenever you find a quiet moment.”','🧙');return}
if(near(16,7)){if(!game.shards[game.zone]){game.shards[game.zone]=true;game.coins+=25;game.flags[`shrine${game.zone}`]=true;log(`The ${zones[game.zone].name} resonance shard sings in your hands.`);toast(`Resonance shard found · +25 glowstones`);if(game.shards.every(Boolean)){dialog('The Threefold Song','The three notes braid together. Across the sky, the islands drift closer. A bright path opens back to Rowan.','✨',()=>{game.flags.threefold=true;save();renderAll()})}}else{toast('The shrine hums softly. This place remembers you.')}save();renderAll();return}
if(game.zone===0&&near(7,8)){dialog('Trail sign','Luma Village → Prismwild Coast (1 shard) → Starfall Canopy (2 shards). Wild companions gather in tall grass. A lattice pod can invite them into your weave.','🪧');return}
if(game.zone>0&&near(10,6)){dialog('Wayfarer','“That Loom! I saw one weave a cloud and a pebble together. The result was a little thunderhead with a stubborn heart.”','🧭');return}promptCheck()}
function dialog(title,text,emoji='💬',after){const el=$('#dialogBody');el.innerHTML=`<div class="dialog-card"><div class="big">${emoji}</div><h2>${title}</h2><p>${text}</p><div class="dialog-actions"><button class="primary" id="dialogOk">Understood</button></div></div>`;$('#dialogModal').classList.add('open');$('#dialogOk').onclick=()=>{$('#dialogModal').classList.remove('open');if(after)after()}}
function move(dx,dy){if(!game.started||game.battle||$$('.modal.open').length||Date.now()<moveLock)return;moveLock=Date.now()+115;game.dir=dy<0?'up':dy>0?'down':dx<0?'left':'right';let nx=game.x+dx,ny=game.y+dy,t=terrain(nx,ny);if(t==='water'||t==='tree')return;game.x=nx;game.y=ny;game.steps++;drawWorld();promptCheck();if(game.zone===0&&t==='grass'&&game.steps%5===0&&Math.random()<.30)beginBattle();else if(game.zone!==0&&t==='grass'&&Math.random()<.14)beginBattle();save()}
function changeZone(z){if(z<0||z>2)return;if(z>0&&game.shards.filter(Boolean).length<z){toast(`Find ${z} shard${z>1?'s':''} to open this route.`);return}game.zone=z;game.x=5;game.y=9;$('#mapModal').classList.remove('open');renderAll();toast(`Arrived at ${zones[z].name}`);log(`You reached ${zones[z].name}.`);save()}
function nearbyWild(){const pool=getZoneSpecies(game.zone).filter(s=>!starters.includes(s.id)||game.seen.includes(s.id));return pool[Math.floor(Math.random()*pool.length)]||species[3]}
function beginBattle(id){if(!game.party.length)return;const s=id?getSpecies(id):nearbyWild();if(!game.seen.includes(s.id))game.seen.push(s.id);const lvl=Math.max(2,Math.floor(Math.random()*4)+2+game.zone*2);game.battle={foe:makeCreature(s.id,lvl),active:0,turn:0};$('#battle').classList.add('active');$('#foeName').textContent=s.name;$('#foeLevel').textContent=`Lv. ${lvl}`;$('#foeArt').textContent=s.emoji;$('#battleCopy').innerHTML=`<b>A wild ${s.name} appeared!</b>What will ${game.party[0].name} do?`;renderBattle();renderAll();log(`A wild ${s.name} crossed your path.`)}
function renderBattle(){if(!game.battle)return;const b=game.battle,c=game.party[b.active],f=b.foe;$('#youArt').textContent=c.emoji;$('#foeHpBar').style.width=`${Math.max(0,100*f.hp/f.max)}%`;$('#foeHpText').textContent=`${Math.max(0,f.hp)} / ${f.max}`;$('#moves').innerHTML=`<button class="move-btn" data-move="0">${c.move}<small>${c.type} · Steady · ${c.atk+4} power</small></button><button class="move-btn" data-move="1">Resonance Burst<small>${c.type} · Strong · ${c.atk+9} power</small></button>`;$$('[data-move]').forEach(x=>x.onclick=()=>attack(+x.dataset.move));$('#podCount').textContent=`×${game.pods}`;$('#captureBtn').disabled=game.pods<1;$('#swapBtn').disabled=game.party.length<2}
function attack(power){if(!game.battle)return;const b=game.battle,c=game.party[b.active],f=b.foe;const dmg=Math.max(2,Math.floor((c.atk+(power?9:4))*(.8+Math.random()*.42)));f.hp=Math.max(0,f.hp-dmg);$('#battleCopy').innerHTML=`<b>${c.name} used ${power?'Resonance Burst':c.move}!</b>${f.name} took ${dmg} damage.`;renderBattle();if(f.hp<=0){setTimeout(victory,420);return}setTimeout(foeTurn,520)}
function foeTurn(){if(!game.battle)return;const b=game.battle,c=game.party[b.active],f=b.foe;const dmg=Math.max(2,Math.floor(f.atk*(.6+Math.random()*.5)));c.hp=Math.max(0,c.hp-dmg);$('#battleCopy').innerHTML=`<b>${f.name} answered with ${f.move}!</b>${c.name} took ${dmg} damage.`;renderBattle();renderParty();if(c.hp<=0){const next=game.party.findIndex(x=>x.hp>0);if(next>=0){b.active=next;$('#battleCopy').innerHTML+=`<br><b>${game.party[next].name} steps forward!</b>`;renderBattle()}else setTimeout(()=>finishBattle(false),500)}}
function victory(){if(!game.battle)return;const c=game.party[game.battle.active],f=game.battle.foe;c.xp+=12+f.level*3;game.coins+=4+f.level;$('#battleCopy').innerHTML=`<b>${f.name} settled down.</b>${c.name} gained ${12+f.level*3} glow XP · +${4+f.level} glowstones.`;if(c.xp>=c.level*20){c.xp-=c.level*20;c.level++;c.max+=3;c.atk++;c.hp=Math.min(c.max,c.hp+8);toast(`${c.name} grew to level ${c.level}!`)}game.defeats++;renderParty();save();setTimeout(()=>finishBattle(true),1000)}
function finishBattle(won){game.battle=null;$('#battle').classList.remove('active');renderAll();save();if(!won){game.party.forEach(c=>c.hp=Math.max(1,Math.floor(c.max*.45)));game.x=5;game.y=9;renderParty();toast('Your team was carried safely back to camp.');save()}}
$('#captureBtn').onclick=()=>{if(!game.battle||game.pods<=0)return;const f=game.battle.foe;game.pods--;const chance=.22+.58*(1-f.hp/f.max);if(Math.random()<chance){const c=makeCreature(f.id,f.level);if(game.party.length<6)game.party.push(c);else game.box.push(c);game.captures++;game.quests.capture=true;$('#battleCopy').innerHTML=`<b>${f.name} joined your weave!</b>${game.party.length<=6?'A new friend, ready for the road.':'Your reserve has room for one more.'}`;if(!game.seen.includes(f.id))game.seen.push(f.id);renderParty();renderBattle();save();setTimeout(()=>finishBattle(true),1050)}else{$('#battleCopy').innerHTML=`<b>The lattice pod wobbled...</b>${f.name} slipped free!`;renderBattle();setTimeout(foeTurn,500)}};
$('#runBtn').onclick=()=>{if(!game.battle)return;if(Math.random()<.8){$('#battleCopy').innerHTML='<b>You made a safe retreat.</b>The wild one watches you go.';setTimeout(()=>finishBattle(true),700)}else{ $('#battleCopy').innerHTML='<b>Not yet!</b>The wild one blocks the path.';setTimeout(foeTurn,500)}};
$('#swapBtn').onclick=()=>{if(!game.battle)return;const available=game.party.map((c,i)=>c.hp>0?i:-1).filter(i=>i>=0);if(available.length<2)return;game.battle.active=available[(available.indexOf(game.battle.active)+1)%available.length];$('#battleCopy').innerHTML=`<b>${game.party[game.battle.active].name}, you're up!</b>Choose a move.`;renderBattle();setTimeout(foeTurn,350)};

