let weavePick=[];
function fusionName(a,b){const x=a.name,y=b.name;let left=x.slice(0,Math.max(3,Math.ceil(x.length*.52))),right=y.slice(Math.floor(y.length*.48));return (left+right.toLowerCase()).replace(/[^a-z]/gi,'').replace(/^./,m=>m.toUpperCase())}
function showFusion(){const el=$('#fusionContent');weavePick=[];if(game.party.length<2){el.innerHTML='<p class="notice">The Loom needs two companions to make a new resonance. Find a friend in the tall grass and invite them with a lattice pod.</p>';return}el.innerHTML=`<p class="notice">Choose two companions. The Resonance Loom braids their traits into an entirely new creature. No friends are lost. Each weave costs 10 glowstones.</p><div class="fusion-grid"><div id="fusionPicks"></div><div class="fusion-plus">＋</div><div id="fusionRight"></div></div><div class="fusion-result" id="fusionResult"><div class="femoji">✧</div><h3>Your weave awaits</h3><p>Choose two distinct companions</p></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px"><span class="tiny-label">GLOWSTONES: <b id="coinCount">${game.coins}</b></span><button class="primary" id="weaveBtn" disabled>Weave resonance · 10 ✧</button></div>`;
const pick=$('#fusionPicks');pick.innerHTML=game.party.map((c,i)=>`<div class="fusion-pick" data-pick="${i}" style="margin-bottom:7px"><span class="femoji">${c.emoji}</span><h3>${c.name}</h3><p>${c.type} · Lv.${c.level}</p></div>`).join('');$('#fusionRight').innerHTML='<div class="fusion-pick" style="min-width:120px"><span class="femoji">✧</span><h3>Second note</h3><p>Choose a partner</p></div>';
$$('[data-pick]').forEach(node=>node.onclick=()=>{let i=+node.dataset.pick;if(weavePick.includes(i)){weavePick=weavePick.filter(x=>x!==i);node.classList.remove('selected')}else if(weavePick.length<2){weavePick.push(i);node.classList.add('selected')}if(weavePick.length===2){const [a,b]=weavePick.map(i=>game.party[i]);const name=fusionName(a,b),emoji=['🦊','🐉','🦄','🐲','🦋','🐯'][((a.name.length+b.name.length)+game.fusions.length)%6],type=a.type===b.type?`${a.type}+`:`${a.type}/${b.type}`,hp=Math.round((a.max+b.max)*.66),atk=Math.round((a.atk+b.atk)*.68);$('#fusionRight').innerHTML=`<div class="fusion-pick selected"><span class="femoji">${b.emoji}</span><h3>${b.name}</h3><p>${b.type} · Lv.${b.level}</p></div>`;$('#fusionResult').innerHTML=`<div class="femoji">${emoji}</div><h3>${name}</h3><p>${type} · ${hp} vitality · ${atk} power</p>`;$('#weaveBtn').disabled=game.coins<10}else{if(weavePick.length===0)$('#fusionRight').innerHTML='<div class="fusion-pick"><span class="femoji">✧</span><h3>Second note</h3><p>Choose a partner</p></div>';$('#fusionResult').innerHTML='<div class="femoji">✧</div><h3>Your weave awaits</h3><p>Choose two distinct companions</p>';$('#weaveBtn').disabled=true}});
$('#weaveBtn').onclick=()=>{if(weavePick.length!==2||game.coins<10)return;const [a,b]=weavePick.map(i=>game.party[i]),name=fusionName(a,b),emoji=['🦊','🐉','🦄','🐲','🦋','🐯'][((a.name.length+b.name.length)+game.fusions.length)%6],f={id:`fusion${Date.now()}`,name,emoji,type:a.type===b.type?`${a.type}+`:`${a.type}/${b.type}`,color:'#a9a0ef',level:Math.max(a.level,b.level),max:Math.round((a.max+b.max)*.66),hp:Math.round((a.max+b.max)*.66),atk:Math.round((a.atk+b.atk)*.68),xp:0,move:'Braided Pulse',fused:true,parents:[a.name,b.name]};game.coins-=10;game.fusions.push(f);game.quests.weave=true;if(game.party.length<6)game.party.push(f);else game.box.push(f);game.seen.push(f.id);toast(`${name} was woven into being!`);log(`The Loom braided ${a.name} + ${b.name} into ${name}.`);save();renderAll();showFusion()};}
function showDex(){const found=game.seen;$('#dexProgress').textContent=`${found.length} resonance${found.length===1?'':'s'} recorded · ${species.length+game.fusions.length} known across the isles`;const list=$('#dexList');const entries=[...species.map(s=>({...s,discovered:found.includes(s.id)})),...game.fusions.map(f=>({...f,discovered:true}))];list.innerHTML=entries.map(s=>`<div class="dex-card" style="${s.discovered?'':'opacity:.42;filter:grayscale(1)'}"><div class="femoji">${s.discovered?s.emoji:'❔'}</div><h3>${s.discovered?s.name:'Unknown resonance'}</h3><p>${s.discovered?s.type:'Not yet found'}</p></div>`).join('')}
