$$('[data-dir]').forEach(b=>{const dir=b.dataset.dir,delta={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];b.addEventListener('pointerdown',e=>{e.preventDefault();move(...delta);b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>{});});
$('#soundBtn').onclick=()=>{const on=$('#soundBtn').dataset.on!=='1';$('#soundBtn').dataset.on=on?'1':'0';$('#soundBtn').textContent=on?'♫':'♪';toast(on?'Sound on':'Sound off')};
setupCanvas();load();renderAll();promptCheck();
</script></body></html>

