 const page=await browser.newPage({viewport:{width:1280,height:900},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002');
 await page.locator('#newGameBtn').click();
 await page.locator('[data-starter="spriggle"]').click();
 await page.locator('#chooseStarter').click();
 if(!(await page.locator('#partyList').innerText()).includes('Spriggle'))throw new Error('starter selection failed');
 await page.locator('[data-modal="mapModal"]').first().click();
 if(!(await page.locator('[data-zone="1"]').getAttribute('class')).includes('locked'))throw new Error('route lock state failed');
 await page.locator('.modal.open .close').click();
 await page.evaluate(()=>{game.x=15;game.y=7;interact()});
 if(await page.locator('#shards .got').count()!==1)throw new Error('home shrine interaction failed');
 await page.locator('[data-modal="mapModal"]').first().click();
 await page.locator('[data-zone="1"]').click();
 if(!(await page.locator('#placeName').innerText()).includes('Prismwild'))throw new Error('route transition failed');
 await page.evaluate(()=>{game.x=15;game.y=7;interact()});
 if(await page.locator('#shards .got').count()!==2)throw new Error('coast shrine interaction failed');
 await page.evaluate(()=>{game.shards=[true,true,true];game.zone=0;game.x=10;game.y=8;game.party[0].level=30;game.party[0].atk=200;game.party[0].hp=game.party[0].max=1000;renderAll();interact()});
 await page.locator('#dialogOk').click();
 if(!(await page.locator('#battle').getAttribute('class')).includes('active'))throw new Error('final encounter did not start');
 if(!(await page.locator('#foeName').innerText()).includes('Rift Warden'))throw new Error('boss title missing');
 if(!(await page.locator('#captureBtn').isDisabled())||!(await page.locator('#runBtn').isDisabled()))throw new Error('boss restrictions missing');
 await page.locator('[data-move="1"]').click();
 await page.waitForTimeout(1700);
 const outcome=await page.evaluate(()=>({champion:game.flags.champion,battle:!!game.battle,objective:document.querySelector('#objective').textContent}));
 if(!outcome.champion)throw new Error('boss victory progression missing '+JSON.stringify(outcome));
 await page.screenshot({path:'screenshots/mythweave-play.jpg',type:'jpeg',quality:78});
 console.log(JSON.stringify({starter:'ok',route:'ok',shrine:'ok',boss:'ok',outcome,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
NODE

